from pathlib import Path
import json,html
R=Path(__file__).resolve().parents[1]
def render():
 p=json.loads((R/'Docs/Development/ProgressV1/progress.json').read_bytes());d=json.loads((R/p['design_source']).read_bytes())
 groups=d['groups']; originals={i['id']:(g,i) for g in groups for i in g['items']}
 e=html.escape
 cards=[]
 for row in p['items']:
  g,i=originals[row['id']]
  links=' '.join('<a href="../../../'+e(x)+'">'+e(x)+'</a>' for x in row['evidence'])
  cards.append('<article data-status="'+row['status']+'" data-group="'+g['id']+'"><h2>'+e(row['id']+' '+i['title'])+'</h2><span class="tag">'+e(p['statuses'][row['status']])+'</span><p><b>現在：</b>'+e(row['existing'])+'</p><p><b>残り：</b>'+e(row['remaining'])+'</p><details><summary>設計の受入条件・根拠</summary><p>'+e(i['acceptance'])+'</p><div class="links">'+links+'</div></details></article>')
 opts=''.join('<option value="'+g['id']+'">'+e(g['id']+' '+g.get('title',g.get('name','')))+'</option>' for g in groups)
 states=''.join('<option value="'+s+'">'+e(t)+'</option>' for s,t in p['statuses'].items())
 near=''.join('<li><b>'+e(x['title'])+'</b>：'+e(x['finish'])+'</li>' for x in p['near_term']['remaining'])
 return '<!doctype html><html lang="ja"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>百代鏡 全体進捗</title><style>body{margin:0;background:#f4f2ed;color:#243039;font:16px/1.75 system-ui}main{max-width:1100px;margin:auto;padding:24px}h1{font-size:30px}h2{font-size:20px;margin:0 0 8px}section,article{background:white;border:1px solid #d6d9d8;border-radius:10px;padding:20px;margin:16px 0}small{color:#52616b}.tag{background:#e3ece8;padding:4px 10px;border-radius:6px}input,select{font:inherit;max-width:100%;padding:8px;box-sizing:border-box;margin:4px 4px 4px 0}.links a{display:block;overflow-wrap:anywhere}article[hidden]{display:none}b{color:#264f46}ul{padding-left:24px}@media(max-width:600px){main{padding:12px}section,article{padding:14px}h1{font-size:24px}}</style><main><h1>百代鏡 全体進捗表</h1><small>2026-10-25 一次監査 / 基準 '+e(p['audit_base_commit'][:12])+'</small><section><h2>設計は60枠採用済み。製品の完成とは別です</h2><p>ゲーム機能59枠＋設計管理1枠。通常入口に一部接続30／独立試作3／データ・関連基盤12／設計のみ・主要実装未確認14。</p><p>45枠には再利用できる実装・基盤があり、14枠は主要実装から必要です。全59枠について、製品全体の受入完了はまだ認定していません。これは機能が動かないという意味でも、完成率・工数の割合でもありません。</p></section><section><h2>直近の地域プレイ：残り3作業</h2><ol>'+near+'</ol><p>'+e(p['near_term']['boundary'])+'</p></section><section><h2>検証の範囲</h2><p>基本設計の受入計画170ケースと、既存Coreテスト2208件は別の単位です。両者の全対応付けは未完了です。</p><p>直前工程の実測：Core 2208件成功（入力・DLL・結果一致で再利用）、GPU実行17回・表示等104照合。これは直前工程の範囲の証拠であり、全60枠の検証結果ではありません。今回はゲームを変更せず、進捗表の整合とブラウザ表示を検証しています。</p></section><section><label>検索 <input id="q" placeholder="項目・現在・残り"></label><select id="group"><option value="">全分野</option>'+opts+'</select><select id="status"><option value="">全状態</option>'+states+'</select><p id="count"></p></section>'+''.join(cards)+'<small>更新時は同じBD行の現在・残り・根拠を更新し、60枠を無断で増減しません。<a href="progress.json">監査データ</a></small></main><script>const cards=[...document.querySelectorAll("article")];function filter(){const q=document.getElementById("q"),group=document.getElementById("group"),status=document.getElementById("status");let n=0;for(const c of cards){c.hidden=!!((q.value&&!c.textContent.toLowerCase().includes(q.value.toLowerCase()))||(group.value&&c.dataset.group!==group.value)||(status.value&&c.dataset.status!==status.value));if(!c.hidden)n++}document.getElementById("count").textContent=n+" / 60項目"}for(const id of ["q","group","status"])document.getElementById(id).addEventListener("input",filter);filter()</script></html>'
if __name__=='__main__':(R/'Docs/Development/ProgressV1/index.html').write_text(render(),encoding='utf-8',newline='\n')
